QLabel {
    background-color: rgb(8, 35, 61);

    border-radius: 10px;

    /* 模拟内阴影：设置半透明边框，并让背景扩展进去 */
    border: 1px solid rgba(47, 92, 134, 100);   /* 外部实色边框（可选） */
    /* 关键：用多个背景图层，先画阴影渐变，再画内容渐变 */
border-image: url(:/new/prefix1/Pictures/RunMonPics/RecPic.png);
}

QLabel {
    background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                                stop: 0 rgb(27, 113, 188),
                                stop: 1 rgb(10, 44, 103));

border-top-left-radius: 10px;
border-top-right-radius: 0px;
